    else if (val&lt;0.25) imgVals = [0.5,0.7,0.28];
    else if (val&lt;0.3) imgVals = [0.44,0.64,0.25];
    else if (val&lt;0.35) imgVals = [0.38,0.59,0.21];
    else if (val&lt;0.4) imgVals = [0.31,0.54,0.18];
